import AppKit
import CryptoKit

/// Sinkron clipboard Mac ↔ HP: teks dan gambar.
/// macOS tidak punya notifikasi perubahan clipboard, jadi changeCount diperiksa tiap 0,5 detik.
final class ClipboardSync {
    static let maxTextBytes = 256 * 1024
    static let maxImageBytes = 20 * 1024 * 1024

    /// Konvensi nspasteboard.org: isi yang tidak boleh disinkronkan (password manager, dll).
    private static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]
    private static let jpegType = NSPasteboard.PasteboardType("public.jpeg")

    private let client: BridgeClient
    private var timer: Timer?
    private var lastChangeCount = NSPasteboard.general.changeCount
    /// Isi terakhir yang dikirim/diterima ("t:"+teks / "i:"+sha256) — mencegah "gema" bolak-balik.
    private var lastSyncedKey: String?
    private var incoming: IncomingImage?

    private struct IncomingImage {
        let id: String
        let mime: String
        let size: Int
        let sha256: String
        var data = Data()
    }

    var connected = false

    var enabled: Bool {
        didSet { UserDefaults.standard.set(enabled, forKey: "clipboardSync") }
    }

    init(client: BridgeClient) {
        self.client = client
        enabled = UserDefaults.standard.object(forKey: "clipboardSync") as? Bool ?? true
    }

    func start() {
        let t = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in self?.poll() }
        t.tolerance = 0.1
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    // MARK: Mac → HP

    private func poll() {
        let pasteboard = NSPasteboard.general
        guard pasteboard.changeCount != lastChangeCount else { return }
        lastChangeCount = pasteboard.changeCount
        guard enabled, connected else { return }

        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        if !types.isDisjoint(with: Self.privateTypes) {
            Log.info("Clipboard Mac berisi data rahasia/sementara — tidak disinkronkan")
            return
        }
        // File yang disalin dari Finder membawa ikon (TIFF) — jangan kirim ikon sebagai gambar.
        if types.contains(NSPasteboard.PasteboardType.fileURL.rawValue) {
            Log.info("Clipboard Mac berisi file — tidak didukung (hanya teks & gambar)")
            return
        }

        if let text = pasteboard.string(forType: .string), !text.isEmpty {
            sendText(text)
        } else if let (data, mime) = imageData(from: pasteboard) {
            sendImage(data, mime: mime)
        }
    }

    private func sendText(_ text: String) {
        let key = "t:" + text
        guard key != lastSyncedKey else { return }
        guard text.utf8.count <= Self.maxTextBytes else {
            Log.info("Teks clipboard Mac terlalu besar (\(text.utf8.count) byte) — tidak disinkronkan")
            return
        }
        lastSyncedKey = key
        client.send(["t": "CLIPBOARD", "text": text])
        Log.info("Clipboard Mac → HP: teks \(text.count) karakter")
    }

    private func sendImage(_ data: Data, mime: String) {
        let sha = Self.sha256(data)
        let key = "i:" + sha
        guard key != lastSyncedKey else { return }
        guard data.count <= Self.maxImageBytes else {
            Log.info("Gambar clipboard Mac terlalu besar (\(data.count / 1024) KB) — tidak disinkronkan")
            return
        }
        lastSyncedKey = key
        client.sendClipboardImage(data, mime: mime, sha256: sha)
        Log.info("Clipboard Mac → HP: gambar \(mime) \(data.count / 1024) KB")
    }

    /// PNG/JPEG apa adanya; TIFF (mis. dari Preview/screenshot) dikonversi ke PNG.
    private func imageData(from pasteboard: NSPasteboard) -> (Data, String)? {
        if let png = pasteboard.data(forType: .png) { return (png, "image/png") }
        if let jpeg = pasteboard.data(forType: Self.jpegType) { return (jpeg, "image/jpeg") }
        if let tiff = pasteboard.data(forType: .tiff),
           let png = NSBitmapImageRep(data: tiff)?.representation(using: .png, properties: [:]) {
            return (png, "image/png")
        }
        return nil
    }

    // MARK: HP → Mac

    func handle(_ type: String, _ m: Message) {
        guard enabled else { return }
        switch type {
        case "CLIPBOARD":
            if let text = m.string("text") { receiveText(text) }
        case "CLIP_IMAGE_BEGIN":
            guard let id = m.string("id"), let size = m.int("size"), size > 0, size <= Self.maxImageBytes,
                  let sha = m.string("sha256") else { return }
            incoming = IncomingImage(id: id, mime: m.string("mime") ?? "image/png", size: size, sha256: sha)
            incoming?.data.reserveCapacity(size)
        case "CLIP_IMAGE_DATA":
            guard let id = m.string("id"), incoming?.id == id, let chunk = m.base64("data") else { return }
            incoming?.data.append(chunk)
            if (incoming?.data.count ?? 0) > (incoming?.size ?? 0) { incoming = nil }
        case "CLIP_IMAGE_END":
            guard let image = incoming, m.string("id") == image.id else { return }
            incoming = nil
            guard image.data.count == image.size, Self.sha256(image.data) == image.sha256 else {
                Log.info("Gambar dari HP rusak/tidak lengkap — dibuang")
                return
            }
            receiveImage(image.data, sha256: image.sha256)
        default:
            break
        }
    }

    private func receiveText(_ text: String) {
        let key = "t:" + text
        guard !text.isEmpty, key != lastSyncedKey else { return }
        lastSyncedKey = key
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        lastChangeCount = pasteboard.changeCount // jangan dikirim balik
        Log.info("Clipboard HP → Mac: teks \(text.count) karakter")
    }

    private func receiveImage(_ data: Data, sha256: String) {
        guard let image = NSImage(data: data) else {
            Log.info("Gambar dari HP tidak bisa dibaca macOS")
            return
        }
        lastSyncedKey = "i:" + sha256
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.writeObjects([image]) // TIFF, dibaca hampir semua aplikasi
        if let png = NSBitmapImageRep(data: data)?.representation(using: .png, properties: [:]) {
            pasteboard.setData(png, forType: .png)
        }
        lastChangeCount = pasteboard.changeCount
        Log.info("Clipboard HP → Mac: gambar \(Int(image.size.width))×\(Int(image.size.height)), \(data.count / 1024) KB")
    }

    static func sha256(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }
}
